function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const a = input[0], b = input[1], p = input[2], x = input[3];

    let count = 0;

    // Precompute a^n mod p for n up to p-1
    const a_pows = new Array(p);
    a_pows[0] = 1;
    for (let i = 1; i < p; ++i) {
        a_pows[i] = (a_pows[i-1] * a) % p;
    }

    // For each possible remainder r of n mod (p-1), find the required n mod p
    for (let r = 0; r < p-1; ++r) {
        const a_r = a_pows[r]; // a^r mod p
        // We need n * a_r ≡ b mod p
        // Solve for n mod p: n ≡ b * a_r^{-1} mod p
        // Find modular inverse of a_r mod p
        let inv_a_r;
        if (a_r === 0) {
            // a_r is 0, so equation becomes 0 ≡ b mod p
            // Only possible if b ≡ 0 mod p, but b < p and b >= 1, so impossible
            continue;
        } else {
            // Compute inverse using Fermat's little theorem
            inv_a_r = modPow(a_r, p-2, p);
        }
        const target_n_mod_p = (b * inv_a_r) % p;

        // Now n ≡ r mod (p-1) and n ≡ target_n_mod_p mod p
        // Use CRT to find n mod (p*(p-1))
        // n = r + k*(p-1)
        // r + k*(p-1) ≡ target_n_mod_p mod p
        // k*(p-1) ≡ (target_n_mod_p - r) mod p
        // Since p-1 ≡ -1 mod p, we have -k ≡ (target_n_mod_p - r) mod p
        // So k ≡ (r - target_n_mod_p) mod p
        const k_mod_p = (r - target_n_mod_p + p) % p;
        const n0 = r + k_mod_p * (p - 1);
        const period = p * (p - 1);

        // Now find all n in [1, x] such that n ≡ n0 mod period
        if (n0 > x) continue;
        count += 1 + Math.floor((x - n0) / period);
    }

    console.log(count);
}

function modPow(base, exp, mod) {
    let result = 1n;
    let b = BigInt(base) % BigInt(mod);
    let e = BigInt(exp);
    const m = BigInt(mod);
    while (e > 0n) {
        if (e & 1n) result = (result * b) % m;
        b = (b * b) % m;
        e >>= 1n;
    }
    return Number(result);
}

main();
