const fs = require('fs');
const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(' ');
const a = BigInt(input[0]);
const b = BigInt(input[1]);
const p = BigInt(input[2]);
const x = BigInt(input[3]);

// Precompute a^m mod p for m from 0 to p-2
const am = new Array(Number(p));
am[0] = 1n;
for (let i = 1n; i < p; i++) {
    am[Number(i)] = (am[Number(i - 1n)] * a) % p;
}

// Precompute modular inverses for 1 to p-1 using Fermat's little theorem
const inv = new Array(Number(p));
inv[1] = 1n;
for (let i = 2n; i < p; i++) {
    inv[Number(i)] = (p - (p / i) * inv[Number(p % i)] % p) % p;
}

let count = 0n;
for (let m = 0n; m < p - 1n; m++) {
    const am_val = am[Number(m)];
    if (am_val === 0n) continue;
    const inv_am = inv[Number(am_val)];
    const c = (b * inv_am) % p;
    const k = (m * inv_am) % p;
    // Find the smallest n >=1 such that n ≡k mod p and n ≡m mod (p-1)
    // Use CRT
    const mod1 = p;
    const mod2 = p - 1n;
    // Solve n ≡k mod mod1, n ≡m mod mod2
    // Check if (k - m) is divisible by gcd(mod1, mod2)
    const g = gcd(mod1, mod2);
    if ((k - m) % g !== 0n) continue;
    // Find solution using extended Euclidean algorithm
    const [x_gcd, y_gcd] = extendedGcd(mod1, mod2);
    const lcm = (mod1 / g) * mod2;
    let n0 = (k + (m - k) * (mod1 / g) * x_gcd) % lcm;
    if (n0 < 0n) n0 += lcm;
    // Now n0 is the smallest non-negative solution
    // Find the smallest n >=1
    let n_min = n0;
    if (n_min === 0n) n_min = lcm;
    if (n_min > x) continue;
    // Count numbers n_min, n_min + lcm, ... <=x
    const max_n = x;
    const count_m = (max_n - n_min) / lcm + 1n;
    count += count_m;
}
console.log(count.toString());

function gcd(a, b) {
    while (b !== 0n) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

function extendedGcd(a, b) {
    if (b === 0n) {
        return [1n, 0n];
    }
    const [x, y] = extendedGcd(b, a % b);
    return [y, x - (a / b) * y];
}
