const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const a = input[0], b = input[1], p = input[2], x = input[3];

// Precompute a^n mod p for n from 1 to p-1
const a_pow = new Array(p);
a_pow[0] = 1;
for (let i = 1; i < p; i++) {
    a_pow[i] = (a_pow[i-1] * a) % p;
}

// Precompute modular inverses of a^n mod p for n from 1 to p-1
const inv_a_pow = new Array(p);
for (let n = 1; n < p; n++) {
    inv_a_pow[n] = modInverse(a_pow[n], p);
}

// Precompute (b * inv(a^n)) mod p for n from 1 to p-1
const target = new Array(p);
for (let n = 1; n < p; n++) {
    target[n] = (b * inv_a_pow[n]) % p;
}

let count = 0;

// Check all possible n from 1 to x
for (let n = 1; n <= x; n++) {
    const m = n % (p - 1);
    const m_val = m === 0 ? p - 1 : m;
    if (m_val === 0) continue; // shouldn't happen since m is in [1, p-1]
    const t = target[m_val];
    if (n % p === t) {
        count++;
    }
}

console.log(count);

function modInverse(a, m) {
    let m0 = m;
    let y = 0, x = 1;
    if (m === 1) return 0;
    while (a > 1) {
        const q = Math.floor(a / m);
        let t = m;
        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) x += m0;
    return x;
}
