const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const a = input[0];
const b = input[1];
const p = input[2];
const x = input[3];

// Precompute a_inv = a^{-1} mod p
const a_inv = modInverse(a, p);

// Precompute a_inv_powers[i] = a_inv^i mod p for i from 0 to p-2
const a_inv_powers = new Array(p - 1);
a_inv_powers[0] = 1;
for (let i = 1; i < p - 1; i++) {
    a_inv_powers[i] = (a_inv_powers[i - 1] * a_inv) % p;
}

// Precompute log_table: log_table[v] = k where a^k ≡ v mod p, for v in 1..p-1
const log_table = new Array(p);
let current = 1;
for (let k = 0; k < p - 1; k++) {
    log_table[current] = k;
    current = (current * a) % p;
}

let count = 0;

for (let r = 0; r < p - 1; r++) {
    const c = (b * a_inv_powers[r]) % p;
    const k = log_table[c];
    if (k === undefined) continue;
    if (k < r) continue;
    const m = (k - r) / (p - 1);
    const n0 = r + m * p;
    if (n0 > x) continue;
    const max_n = r + ((x - r) / p) * p;
    if (max_n < n0) continue;
    const terms = ((max_n - n0) / p) + 1;
    count += terms;
}

console.log(count);

function modInverse(a, p) {
    return modPow(a, p - 2, p);
}

function modPow(base, exp, mod) {
    let result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 === 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp = Math.floor(exp / 2);
    }
    return result;
}
